def extract_date(text):
    # Common date patterns
    patterns = [
        r'(\d{1,2})[/\-\.](\d{1,2})[/\-\.](\d{2,4})',  # DD/MM/YYYY
        r'(\d{4})[/\-\.](\d{1,2})[/\-\.](\d{1,2})',  # YYYY/MM/DD
        r'(\d{1,2})\s+(JAN|FEB|MAR|APR|MAY|JUN|JUL|AUG|SEP|OCT|NOV|DEC)[A-Z]*\s+(\d{2,4})', # DD MMM YYYY
    ]

    months = {
        'JAN': '01', 'FEB': '02', 'MAR': '03', 'APR': '04', 'MAY': '05', 'JUN': '06',
        'JUL': '07', 'AUG': '08', 'SEP': '09', 'OCT': '10', 'NOV': '11', 'DEC': '12'
    }

    lines = text.split('\n')
    for line in lines:
        for pattern in patterns:
            match = re.search(pattern, line, re.IGNORECASE)
            if match:
                groups = match.groups()
                if len(groups) == 3:
                    if re.search(r'[A-Z]{3}', str(groups[1]), re.IGNORECASE): # DD MMM YYYY
                        day, month_str, year = groups
                        month = months.get(month_str.upper()[:3])
                    elif len(groups[0]) == 4: # YYYY/MM/DD
                        year, month, day = groups
                    else: # DD/MM/YYYY
                        day, month, year = groups

                    if len(str(year)) == 2:
                        year = '20' + str(year)

                    try:
                        day_int = int(day)
                        month_int = int(month)
                        year_int = int(year)
                        if 1 <= month_int <= 12 and 1 <= day_int <= 31 and 1900 < year_int < 2100:
                            return f"{year_int:04d}-{month_int:02d}-{day_int:02d}"
                    except:
                        continue
    # Special case for DDMMYYYY or DMMYYYY
    match = re.search(r'\b(\d{1,2})(\d{2})(\d{4})\b', text)
    if match:
        day, month, year = match.groups()
        try:
            day_int = int(day)
            month_int = int(month)
            year_int = int(year)
            if 1 <= month_int <= 12 and 1 <= day_int <= 31:
                return f"{year_int:04d}-{month_int:02d}-{day_int:02d}"
        except: pass

    return None

def clean_amount(s):
    if not s: return None
    # Remove currency and spaces
    s = re.sub(r'[^\d.,]', '', s)
    # Handle cases like 1,234.56
    if ',' in s and '.' in s:
        if s.find(',') < s.find('.'):
            s = s.replace(',', '')
        else:
            s = s.replace('.', '').replace(',', '.')
    elif ',' in s:
        # Check if comma is decimal separator (e.g. 10,00)
        parts = s.split(',')
        if len(parts[-1]) == 2:
            s = s.replace(',', '.')
        else:
            s = s.replace(',', '')

    try:
        val = float(s)
        return f"{val:.2f}"
    except:
        return None

def extract_total(text):
    priority_keywords = [
        ['GRAND TOTAL'],
        ['TOTAL RM', 'TOTAL: RM'],
        ['TOTAL AMOUNT'],
        ['TOTAL', 'AMOUNT', 'TOTAL DUE', 'AMOUNT DUE', 'BALANCE DUE', 'NETT TOTAL', 'NET TOTAL']
    ]

    exclude_keywords = [
        'SUBTOTAL', 'SUB TOTAL', 'TAX', 'GST', 'SST', 'DISCOUNT', 'CHANGE', 'CASH TENDERED'
    ]

    lines = text.split('\n')
    lines = [line.strip() for line in lines if line.strip()]

    amount_pattern = r'(\d{1,3}(?:[.,\s]\d{3})*[.,]\d{2})\b'

    for kw_list in priority_keywords:
        for kw in kw_list:
            for i, line in enumerate(lines):
                if kw in line.upper():
                    # Check exclusions
                    if any(ex in line.upper() for ex in exclude_keywords if ex not in kw):
                        continue

                    # Try same line
                    match = re.findall(amount_pattern, line)
                    if match:
                        val = clean_amount(match[-1])
                        if val: return val

                    # Try next line
                    if i + 1 < len(lines):
                        next_line = lines[i+1]
                        if not any(ex in next_line.upper() for ex in exclude_keywords):
                            match = re.findall(amount_pattern, next_line)
                            if match:
                                val = clean_amount(match[-1])
                                if val: return val

    return None

